  if (!selected) return <Empty>برای مشاهده جزئیات، یک کلاس را انتخاب کنید.</Empty>;
  async function runAction(action) {
    try {
      const result = await action();
      if (result?.url) setStudentUrl(result.url);
      if (result?.publicUrl) setPublicUrl(result.publicUrl);
      if (result?.streamKey) setIngress(result);
      setAccessMessage("عملیات با موفقیت انجام شد.");
    } catch (error) {
      setAccessMessage(error.message || "عملیات انجام نشد.");
    }
  }
  const streamKey = legacy?.streamKeyField || (legacy?.streamKey ? `${legacy.username}?key=${legacy.streamKey}` : "");
  const classUrl = typeof window !== "undefined" ? `${window.location.origin}/channel/${selected.channel}` : `/channel/${selected.channel}`;
  return <div className="space-y-4"><Card><CardHeader><CardTitle className="flex items-center justify-between gap-3"><span>{labelOf(selected)}</span><Badge variant={selected.visibility === "public" ? "default" : "secondary"}>{selected.visibility === "public" ? "عمومی" : "خصوصی"}</Badge></CardTitle></CardHeader><CardContent className="space-y-3 text-sm"><p className="text-muted-foreground">{selected.description || "توضیحی برای این کلاس ثبت نشده است."}</p><div className="grid gap-2 text-xs text-muted-foreground sm:grid-cols-3"><span dir="ltr">slug: {selected.slug}</span><span dir="ltr">channel: {selected.channel}</span><span>ایجاد: {dateOf(selected.createdAt)}</span></div></CardContent></Card><div className="grid gap-4 lg:grid-cols-2"><Card><CardHeader><CardTitle className="text-base">کلاس و Streaming</CardTitle></CardHeader><CardContent className="space-y-4"><CopyField label="لینک ورود کلاس" value={classUrl} /><Button size="sm" onClick={() => window.open(classUrl, "_blank", "noopener,noreferrer")}><ExternalLink className="size-4" /> ورود به کلاس</Button><CopyField label="LiveKit API URL" value={legacy?.livekitIngressUrl} /><CopyField label="RTMP URL" value={legacy?.rtmpServer || RTMP_URL} /><CopyField label="Stream Key" value={streamKey} secret /><div className="flex flex-wrap gap-2"><Button size="sm" variant="outline" onClick={() => void runAction(() => api.createTestLink(selected.channel, "دانش‌آموز تستی"))}><ExternalLink className="size-4" /> لینک تست دانش‌آموز</Button><Button size="sm" variant="outline" onClick={() => void runAction(() => api.setClassAccess(selected.channel, "public"))}>لینک همگانی</Button><Button size="sm" variant="outline" onClick={() => void runAction(() => api.createIngress(selected.channel))}>دریافت کلید LiveKit</Button></div>{studentUrl && <CopyField label="لینک تست" value={studentUrl} />}{publicUrl && <CopyField label="لینک همگانی" value={publicUrl} />}{ingress && <div className="space-y-2"><CopyField label="LiveKit Server" value={ingress.url} /><CopyField label="LiveKit Stream Key" value={ingress.streamKey} secret /></div>}{accessMessage && <p className="text-xs text-muted-foreground">{accessMessage}</p>}</CardContent></Card><Card><CardHeader><CardTitle className="flex items-center justify-between text-base"><span>جلسه‌ها</span><Button size="sm" onClick={onStartSession}><Plus className="size-4" /> جلسه</Button></CardTitle></CardHeader><CardContent>{sessions.length ? <div className="space-y-2">{sessions.map((session) => <div key={session._id} className="rounded-md border p-3 text-sm"><div className="flex items-center justify-between gap-2"><span>{session.startedAt ? dateOf(session.startedAt) : "بدون زمان"}</span><Badge variant={session.status === "live" ? "default" : "secondary"}>{session.status === "live" ? "زنده" : session.status === "ended" ? "پایان‌یافته" : "زمان‌بندی‌شده"}</Badge></div>{session.endedAt && <p className="mt-1 text-xs text-muted-foreground">پایان: {dateOf(session.endedAt)}</p>}{session.metadata?.description && <p className="mt-1 text-xs text-muted-foreground">{session.metadata.description}</p>}</div>)}</div> : <Empty>جلسه‌ای ثبت نشده است.</Empty>}</CardContent></Card></div><div className="grid gap-4 lg:grid-cols-2"><Card><CardHeader><CardTitle className="text-base">یادداشت‌های ادمین</CardTitle></CardHeader><CardContent className="space-y-3"><div className="flex gap-2"><Input value={note} placeholder="یادداشت خصوصی برای این کلاس" onChange={(event) => setNote(event.target.value)} /><Button disabled={!note.trim()} onClick={async () => { await onNote(note); setNote(""); }}>ثبت</Button></div>{notes.length ? <div className="space-y-2">{notes.map((item) => <div key={item._id} className="rounded-md border p-3 text-sm"><p>{item.content}</p><p className="mt-2 text-xs text-muted-foreground">{dateOf(item.createdAt)}</p></div>)}</div> : <Empty>یادداشتی ثبت نشده است.</Empty>}</CardContent></Card><Card><CardHeader><CardTitle className="text-base">حضور جلسه اخیر</CardTitle></CardHeader><CardContent>{attendance.length ? <div className="overflow-x-auto"><table className="w-full text-right text-sm"><thead><tr className="border-b text-muted-foreground"><th className="p-2">دانش‌آموز</th><th className="p-2">ورود</th><th className="p-2">خروج</th></tr></thead><tbody>{attendance.map((row) => <tr key={row._id} className="border-b last:border-0"><td className="p-2">{row.studentId?.name || row.studentId?.externalId || "دانش‌آموز"}</td><td className="p-2">{dateOf(row.joinedAt)}</td><td className="p-2">{row.leftAt ? dateOf(row.leftAt) : "آنلاین"}</td></tr>)}</tbody></table></div> : <Empty>برای این کلاس حضور و غیابی ثبت نشده است.</Empty>}</CardContent></Card></div></div>;
